/* rampart-sim development copy */
function rampartSimulate(createStrategy, seed, maxTicks) {
  "use strict";

  // ---- static data ----
  var TURRET_ORDER = ["bolt", "cannon", "frost", "lance", "flak"];
  var TURRETS = {
    bolt:   { cost: 50,  dmg: 26,  period: 8,  range: 300, splash: 0,  slow: 0,  pierce: false, ground: true,  air: true  },
    cannon: { cost: 90,  dmg: 60,  period: 24, range: 260, splash: 90, slow: 0,  pierce: false, ground: true,  air: false },
    frost:  { cost: 70,  dmg: 10,  period: 12, range: 240, splash: 0,  slow: 30, pierce: false, ground: true,  air: true  },
    lance:  { cost: 120, dmg: 180, period: 36, range: 360, splash: 0,  slow: 0,  pierce: true,  ground: true,  air: false },
    flak:   { cost: 80,  dmg: 40,  period: 10, range: 320, splash: 70, slow: 0,  pierce: false, ground: false, air: true  }
  };
  var ENEMY_ORDER = ["grunt", "runner", "wisp", "brute", "splitter", "mender"];
  var ENEMIES = {
    grunt:    { hp: 60,  speed: 10, armor: -1, bounty: 4, leak: 1, air: false, first: 1, weight: 10 },
    runner:   { hp: 40,  speed: 20, armor: 0,  bounty: 4, leak: 1, air: false, first: 2, weight: 4  },
    wisp:     { hp: 50,  speed: 12, armor: 0,  bounty: 6, leak: 2, air: true,  first: 3, weight: 3  },
    brute:    { hp: 150, speed: 6,  armor: -2, bounty: 9, leak: 3, air: false, first: 4, weight: 3  },
    splitter: { hp: 90,  speed: 8,  armor: 0,  bounty: 6, leak: 2, air: false, first: 6, weight: 2  },
    mender:   { hp: 70,  speed: 8,  armor: 0,  bounty: 7, leak: 2, air: false, first: 8, weight: 1  },
    splitling:{ hp: 1,   speed: 12, armor: 0,  bounty: 1, leak: 1, air: false, first: 99, weight: 0 }
  };

  var SLOT_TILES = [
    [3, 3], [5, 5], [7, 4], [7, 8], [9, 9], [10, 5], [11, 8], [13, 8],
    [14, 5], [15, 2], [16, 7], [17, 4], [19, 8], [20, 10], [22, 9], [3, 7]
  ];

  // Ground route points in centi-tiles
  var GROUND_PTS = [
    [50, 250], [650, 250], [650, 1050], [1250, 1050],
    [1250, 350], [1850, 350], [1850, 1150], [2350, 1150]
  ];
  // Air route points in centi-tiles.  Specification text says length 2600;
  // geometry of the listed points is 2800.  AIR_LEN_MODE lets the test
  // harness compare both.
  var AIR_PTS = [
    [50, 650], [2150, 650], [2150, 1150], [2350, 1150]
  ];
  var AIR_GEOM_LEN = 2800;
  var AIR_LEN = (typeof AIR_LEN_MODE !== "undefined" && AIR_LEN_MODE === 2600) ? 2600 : 2800;

  // Precompute route segment metadata
  function makeRoute(pts, forcedLen) {
    var segs = [];
    var total = 0;
    for (var i = 1; i < pts.length; i++) {
      var ax = pts[i - 1][0], ay = pts[i - 1][1];
      var bx = pts[i][0], by = pts[i][1];
      var dx = bx - ax, dy = by - ay;
      var len = Math.abs(dx) + Math.abs(dy);
      var ux = dx === 0 ? 0 : (dx > 0 ? 1 : -1);
      var uy = dy === 0 ? 0 : (dy > 0 ? 1 : -1);
      segs.push({ ax: ax, ay: ay, ux: ux, uy: uy, len: len, start: total });
      total += len;
    }
    return { segs: segs, length: (forcedLen !== undefined ? forcedLen : total), geomLength: total };
  }
  var GROUND_ROUTE = makeRoute(GROUND_PTS);
  var AIR_ROUTE = makeRoute(AIR_PTS, AIR_LEN);

  function routePos(route, progress) {
    var segs = route.segs, n = segs.length;
    var p = progress;
    if (p < 0) p = 0;
    if (p > route.length) p = route.length;
    for (var i = 0; i < n; i++) {
      var s = segs[i];
      if (p <= s.start + s.len) {
        var d = p - s.start;
        return { x: s.ax + s.ux * d, y: s.ay + s.uy * d };
      }
    }
    var last = segs[n - 1];
    return { x: last.ax + last.ux * last.len, y: last.ay + last.uy * last.len };
  }

  function mulberry32(a) {
    return function () {
      a = (a + 0x6D2B79F5) | 0;
      var t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return (t ^ (t >>> 14)) >>> 0;
    };
  }

  // HP multiplier table
  var mTable = [0, 1000];
  function hpMult(w) {
    while (mTable.length <= w) {
      mTable.push(Math.floor(mTable[mTable.length - 1] * 108 / 100));
    }
    return mTable[w];
  }

  // ---- mutable game state ----
  var rng = mulberry32(seed >>> 0);
  var gold = 250;
  var baseHp = 10;
  var slots = [];
  for (var si = 0; si < 16; si++) {
    slots.push({ slot: si, x: SLOT_TILES[si][0], y: SLOT_TILES[si][1], turret: null });
  }
  var enemies = [];
  var nextId = 1;
  var spawnQueue = [];
  var log = [];
  var fallTick = -1;
  var tick = 0;
  var curWave = 0;
  var pendingComp = null;
  var nextComp = null;

  function genWave(w) {
    var pool = [], sum = 0;
    for (var i = 0; i < ENEMY_ORDER.length; i++) {
      var t = ENEMY_ORDER[i];
      if (ENEMIES[t].first <= w) {
        pool.push(t);
        sum += ENEMIES[t].weight;
      }
    }
    var n = 4 + Math.floor(3 * w / 5);
    var out = [];
    for (var k = 0; k < n; k++) {
      var r = rng() % sum;
      var pick = pool[0];
      for (var j = 0; j < pool.length; j++) {
        if (r < ENEMIES[pool[j]].weight) { pick = pool[j]; break; }
        r -= ENEMIES[pool[j]].weight;
      }
      out.push(pick);
    }
    return out;
  }

  function enemyArmor(type, wave) {
    var d = ENEMIES[type];
    if (d.armor === -1) return Math.floor(wave / 4);
    if (d.armor === -2) return 6 + wave;
    return 0;
  }

  function makeEnemy(id, type, wave, progress, hpOverride) {
    var d = ENEMIES[type];
    var maxHp = hpOverride !== undefined ? hpOverride : Math.floor(d.hp * hpMult(wave) / 1000);
    if (maxHp < 1) maxHp = 1;
    var route = d.air ? AIR_ROUTE : GROUND_ROUTE;
    var pos = routePos(route, progress);
    return {
      id: id,
      type: type,
      wave: wave,
      maxHp: maxHp,
      hp: maxHp,
      progress: progress,
      age: 0,
      slow: 0,
      x: pos.x,
      y: pos.y,
      air: d.air ? 1 : 0,
      armor: enemyArmor(type, wave),
      speed: d.speed,
      remaining: route.length - progress,
      route: route
    };
  }

  function updatePos(e) {
    var pos = routePos(e.route, e.progress);
    e.x = pos.x;
    e.y = pos.y;
    e.remaining = e.route.length - e.progress;
  }

  function enemyView(e) {
    return {
      id: e.id, type: e.type, hp: e.hp, maxHp: e.maxHp,
      x: e.x, y: e.y, air: e.air, armor: e.armor,
      speed: e.speed, slowed: e.slow > 0 ? 1 : 0, remaining: e.remaining
    };
  }

  function turretDamage(type, tier) {
    var d = TURRETS[type].dmg;
    if (tier >= 2) d = Math.floor(d * 16 / 10);
    if (tier >= 3) d = Math.floor(d * 16 / 10);
    return d;
  }
  function turretRange(type, tier) {
    return TURRETS[type].range + 30 * (tier - 1);
  }

  function buildState(w, previewComp) {
    var slotViews = [];
    for (var i = 0; i < 16; i++) {
      var s = slots[i];
      slotViews.push({
        slot: s.slot, x: s.x, y: s.y,
        turret: s.turret ? { type: s.turret.type, tier: s.turret.tier, spent: s.turret.spent } : null
      });
    }
    var ev = [];
    for (var j = 0; j < enemies.length; j++) ev.push(enemyView(enemies[j]));
    return {
      tick: tick, wave: w, gold: gold, baseHp: baseHp,
      slots: slotViews, enemies: ev, nextWave: previewComp.slice()
    };
  }

  function applyPlan(actions) {
    if (!actions || typeof actions.length !== "number") return;
    var limit = Math.min(32, actions.length);
    for (var i = 0; i < limit; i++) {
      var a = actions[i];
      if (!a || typeof a !== "object") continue;
      var slot = a.slot;
      if (typeof slot !== "number" || slot < 0 || slot >= 16 || Math.floor(slot) !== slot) continue;
      var s = slots[slot];
      if (a.op === "build") {
        var type = a.type;
        if (!TURRETS.hasOwnProperty(type)) continue;
        if (s.turret) continue;
        var cost = TURRETS[type].cost;
        if (gold < cost) continue;
        gold -= cost;
        s.turret = { type: type, tier: 1, spent: cost, cd: 0 };
        log.push([tick, "B", slot, TURRET_ORDER.indexOf(type)]);
      } else if (a.op === "upgrade") {
        if (!s.turret) continue;
        if (s.turret.tier >= 3) continue;
        var up = TURRETS[s.turret.type].cost * (s.turret.tier === 1 ? 1 : 2);
        if (gold < up) continue;
        gold -= up;
        s.turret.tier += 1;
        s.turret.spent += up;

