/* Experiment strategies.  Dev-only file. */

var TCOST = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
var TDPS = { bolt: 26/8, cannon: 60/24, frost: 10/12, lance: 180/36, flak: 40/10 };

function mkGreedy(opts) {
  return function createStrategy() {
    var builds = opts.builds;
    var upOrder = opts.upOrder || [];
    var mode = opts.mode || "buildfirst";
    var targetMode = opts.targetMode || "near";
    return {
      plan: function (s) {
        var acts = [];
        var spent = 0;
        var budget = s.gold;
        // current turret lookup
        var slotTurret = {};
        for (var i = 0; i < s.slots.length; i++) slotTurret[s.slots[i].slot] = s.slots[i].turret;
        var built = {};
        for (var bi = 0; bi < builds.length; bi++) {
          if (slotTurret[builds[bi][0]]) built[builds[bi][0]] = true;
        }
        function afford(c) { return budget >= c; }
        function doBuild(slot, type) {
          var c = TCOST[type];
          if (afford(c) && !slotTurret[slot]) {
            budget -= c; slotTurret[slot] = { type: type, tier: 1 };
            acts.push({ op: "build", slot: slot, type: type });
            return true;
          }
          return false;
        }
        function doUp(slot) {
          var tu = slotTurret[slot];
          if (!tu || tu.tier >= 3) return false;
          var c = TCOST[tu.type] * (tu.tier === 1 ? 1 : 2);
          if (afford(c)) {
            budget -= c; tu.tier += 1;
            acts.push({ op: "upgrade", slot: slot });
            return true;
          }
          return false;
        }
        if (mode === "buildfirst") {
          for (var b = 0; b < builds.length; b++) doBuild(builds[b][0], builds[b][1]);
          // upgrades repeatedly in priority order
          var changed = true;
          while (changed && acts.length < 32) {
            changed = false;
            for (var u = 0; u < upOrder.length && acts.length < 32; u++) {
              if (doUp(upOrder[u])) changed = true;
            }
          }
        } else if (mode === "upfirst") {
          var changed2 = true;
          while (changed2 && acts.length < 32) {
            changed2 = false;
            for (var u2 = 0; u2 < upOrder.length && acts.length < 32; u2++) {
              if (doUp(upOrder[u2])) changed2 = true;
            }
            for (var b2 = 0; b2 < builds.length && acts.length < 32; b2++) {
              if (doBuild(builds[b2][0], builds[b2][1])) changed2 = true;
            }
          }
        } else if (mode === "mixed") {
          // alternate one upgrade, one build, following orders
          var ui = 0, b3 = 0;
          while (acts.length < 32) {
            var did = false;
            while (ui < upOrder.length) { if (doUp(upOrder[ui])) { did = true; } ui++; break; }
            while (b3 < builds.length) { if (doBuild(builds[b3][0], builds[b3][1])) { did = true; } b3++; break; }
            if (!did) break;
          }
        }
        return acts;
      },
      target: function (t, c) {
        if (targetMode === "near") {
          var best = c[0];
          for (var i = 1; i < c.length; i++) {
            if (c[i].remaining < best.remaining ||
              (c[i].remaining === best.remaining && c[i].id < best.id)) best = c[i];
          }
          return best.id;
        } else if (targetMode === "lowhp") {
          var b2 = c[0];
          for (var j = 1; j < c.length; j++) {
            if (c[j].hp < b2.hp || (c[j].hp === b2.hp && c[j].remaining < b2.remaining)) b2 = c[j];
          }
          return b2.id;
        } else if (targetMode === "frost") {
          var b3 = null;
          for (var k = 0; k < c.length; k++) {
            if (!c[k].slowed) { if (!b3 || c[k].remaining < b3.remaining) b3 = c[k]; }
          }
          if (b3) return b3.id;
          var b4 = c[0];
          for (var k2 = 1; k2 < c.length; k2++) if (c[k2].remaining < b4.remaining) b4 = c[k2];
          return b4.id;
        } else if (targetMode === "mender") {
          var b5 = null;
          for (var k3 = 0; k3 < c.length; k3++) if (c[k3].type === "mender") { if (!b5 || c[k3].remaining < b5.remaining) b5 = c[k3]; }
          if (b5) return b5.id;
          var b6 = c[0];
          for (var k4 = 1; k4 < c.length; k4++) if (c[k4].remaining < b6.remaining) b6 = c[k4];
          return b6.id;
        }
        return c[0].id;
      }
    };
  };
}

var ALL_SLOTS = [12, 8, 11, 1, 0, 3, 6, 5, 13, 2, 10, 7, 4, 9, 15, 14];

function bench(strategyFactory, seeds, maxTicks) {
  maxTicks = maxTicks || 12020;
  var out = [];
  for (var i = 0; i < seeds.length; i++) {
    var r = rampartSimulate(strategyFactory, seeds[i], maxTicks);
    out.push({ seed: seeds[i], score: r.score, fallTick: r.fallTick, n: r.log.length });
  }
  var sum = 0;
  for (var j = 0; j < out.length; j++) sum += out[j].score;
  return { mean: Math.round(sum / out.length * 100) / 100, out: out };
}

