/* Composition experiment helpers */
var GORDER = [12,8,11,0,3,6,4,9,13,1,5,2,10,7,15,14];
var AORDER = [12,8,11,1,5,13,2,10,14,15,3,7,6,0,9,4];
var BORDER = [12,8,11,1,0,3,6,5,13,2,10,7,4,9,15,14];

function assignTypes(counts) {
  // counts: {lance, flak, cannon, bolt, frost}
  var out = {};
  var used = {};
  function take(order, type, n) {
    var k = 0;
    for (var i = 0; i < order.length && k < n; i++) {
      if (used[order[i]]) continue;
      out[order[i]] = type; used[order[i]] = true; k++;
    }
  }
  take(AORDER, "flak", counts.flak || 0);
  take(GORDER, "lance", counts.lance || 0);
  // cannon also prefers ground coverage
  take(GORDER, "cannon", counts.cannon || 0);
  take(AORDER, "frost", counts.frost || 0);
  take(BORDER, "bolt", counts.bolt || 0);
  // fill remaining with bolt
  for (var s = 0; s < 16; s++) if (!out[s]) out[s] = "bolt";
  return out;
}

function mkComp(counts, buildOrder, upOrder, mode, targetMode) {
  var typeBySlot = assignTypes(counts);
  var order = buildOrder || BORDER;
  var builds = order.map(function (s) { return [s, typeBySlot[s]]; });
  var ups = upOrder || order;
  return mkGreedy({ builds: builds, upOrder: ups, mode: mode || "buildfirst", targetMode: targetMode });
}

