def climb(pg, start, max_rounds=8):
    cur = list(start)
    best = fit(pg, cur)
    print("start", best, cur, flush=True)
    for rnd in range(max_rounds):
        movers = []
        for i in range(16):
            for t in TYPES:
                if t == cur[i]: continue
                cand = list(cur); cand[i] = t
                v = fit(pg, cand)
                if v > best + 1e-9:
                    movers.append((v, i, t))
        # also try pair swaps of slot types (different types) ~120 combos
        for i in range(16):
            for j in range(i+1,16):
                if cur[i] == cur[j]: continue
                cand = list(cur); cand[i],cand[j] = cand[j],cand[i]
                v = fit(pg, cand)
                if v > best + 1e-9:
                    movers.append((v, i, j))
        if not movers:
            print("no improvement", rnd, flush=True); break
        movers.sort(reverse=True)
        v, a, b = movers[0]
        if isinstance(b, str):
            cur[a] = b
        else:
            cur[a], cur[b] = cur[b], cur[a]
        best = v
        print("round", rnd, "->", best, cur, flush=True)
    return best, cur

