      return bench(f,seeds);
    }""", cur)
    print("VALID", json.dumps(val), flush=True)
    with open(BASE+"/search2_results.json","w") as fh:
        json.dump({"types":cur,"train":best,"valid":val}, fh, indent=2)
finally:
    b.close(); p.stop()

