function createStrategy() {
  // Final static plan: 9 cannons, 4 bolts, 3 flaks.
  var BUILD_ORDER = [12, 8, 11, 1, 0, 3, 6, 5, 13, 2, 10, 7, 4, 9, 15, 14];
  var PLAN_TYPE = {
    0: "flak", 1: "bolt", 2: "bolt", 3: "cannon",
    4: "cannon", 5: "flak", 6: "cannon", 7: "cannon",
    8: "cannon", 9: "cannon", 10: "cannon", 11: "cannon",
    12: "bolt", 13: "cannon", 14: "bolt", 15: "flak"
  };
  var COST = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };

  return {
    plan: function (s) {
      var acts = [];
      var budget = s.gold;
      var turret = [];
      var i, slot, tu;
      for (i = 0; i < s.slots.length; i++) {
        var sl = s.slots[i];
        turret[sl.slot] = sl.turret ? { type: sl.turret.type, tier: sl.turret.tier } : null;
      }

      // Build every assigned slot as soon as it is affordable.
      for (i = 0; i < BUILD_ORDER.length; i++) {
        slot = BUILD_ORDER[i];
        if (!turret[slot]) {
          var type = PLAN_TYPE[slot];
          var c = COST[type];
          if (budget >= c) {
            budget -= c;
            turret[slot] = { type: type, tier: 1 };
            acts.push({ op: "build", slot: slot, type: type });
          }
        }
      }

      // Buy the cheapest available upgrade first.
      var again = true;
      while (again && acts.length < 32) {
        again = false;
        var bestSlot = -1;
        var bestCost = 1e9;
        for (i = 0; i < BUILD_ORDER.length; i++) {
          slot = BUILD_ORDER[i];
          tu = turret[slot];
          if (!tu || tu.tier >= 3) continue;
          var up = COST[tu.type] * (tu.tier === 1 ? 1 : 2);
          if (up < bestCost) { bestCost = up; bestSlot = slot; }
        }
        if (bestSlot >= 0 && budget >= bestCost) {
          budget -= bestCost;
          turret[bestSlot].tier += 1;
          acts.push({ op: "upgrade", slot: bestSlot });
          again = true;
        }
      }
      return acts;
    },

    target: function (t, c) {
      var i, j;
      // Menders first: their unbroken healing is the biggest force multiplier.
      var mend = null;
      for (i = 0; i < c.length; i++) {
        if (c[i].type === "mender") {
          if (!mend || c[i].remaining < mend.remaining) mend = c[i];
        }
      }
      if (mend) return mend.id;

      var splash = t.type === "cannon" ? 90 : (t.type === "flak" ? 70 : 0);
      if (splash > 0) {
        // Aim where the splash lands on the most enemies.
        var bestScore = -1;
        var bestId = c[0].id;
        for (i = 0; i < c.length; i++) {
          var count = 0;
          for (j = 0; j < c.length; j++) {
            var dx = c[j].x - c[i].x;
            var dy = c[j].y - c[i].y;
            if (dx * dx + dy * dy <= splash * splash) count++;
          }
          var score = count * 100000 - c[i].remaining;
          if (score > bestScore) { bestScore = score; bestId = c[i].id; }
        }
        return bestId;
      }

      var best = c[0];
      for (i = 1; i < c.length; i++) {
        if (c[i].remaining < best.remaining ||
            (c[i].remaining === best.remaining && c[i].id < best.id)) {
          best = c[i];
        }
      }
      return best.id;
    }
  };
}

