// ============================================================
// Playback state machine, controls and render loop
// ============================================================
var COUNTDOWN = "COUNTDOWN";
var PLAYING = "PLAYING";
var PAUSED = "PAUSED";
var REFIRE_HOLD = "REFIRE_HOLD";
var ENDED = "ENDED";

var playbackState = COUNTDOWN;
var playbackSpeed = 1.0;
var simTime = 0;
var countdownElapsed = 0;
var holdElapsed = 0;
var lastWall = null;
var booted = false;

var countdownEl = document.getElementById("countdown");
var btnToggle = document.getElementById("btn-toggle");
var btnRefire = document.getElementById("btn-refire");
var iconPause = document.getElementById("icon-pause");
var iconPlay = document.getElementById("icon-play");
var scrubber = document.getElementById("scrubber");
var speedPills = Array.prototype.slice.call(document.querySelectorAll(".speed-pill"));

function setPlayIcons(playing) {
  iconPause.style.display = playing ? "" : "none";
  iconPlay.style.display = playing ? "none" : "";
  btnToggle.setAttribute("aria-label", playing ? "Pause" : "Play");
}
function hideCountdown() {
  countdownEl.style.display = "none";
  countdownEl.textContent = "";
}
function showCountdownText(txt) {
  countdownEl.style.display = "block";
  countdownEl.textContent = txt;
}
function setScrubberValue(v) {
  scrubber.value = v;
}

function enterPlaying() {
  playbackState = PLAYING;
  lastWall = null;
  setPlayIcons(true);
  hideCountdown();
  setAudioAudible(true);
  resetAudioCursor(simTime);
}
function enterPaused() {
  playbackState = PAUSED;
  setPlayIcons(false);
  setAudioAudible(false);
  resetAudioCursor(simTime);
}
function enterEnded() {
  simTime = DURATION;
  setScrubberValue(DURATION.toFixed(3));
  renderScene(DURATION);
  playbackState = ENDED;
  setPlayIcons(false);
  setAudioAudible(false);
}
function enterRefire() {
  hideCountdown();
  simTime = 0;
  countdownElapsed = 0;
  holdElapsed = 0;
  setScrubberValue("0");
  renderScene(0);
  setPlayIcons(true);
  setAudioAudible(false);
  resetAudioCursor(0);
  playbackState = REFIRE_HOLD;
}

function updateCountdownDisplay() {
  if (countdownElapsed < 1) showCountdownText("3");
  else if (countdownElapsed < 2) showCountdownText("2");
  else showCountdownText("1");
}

function renderScene(t) {
  var wt = HAS_FALL ? Math.min(t, FALL_TIME) : t;
  if (HAS_FALL && t >= FALL_TIME - 0.0000001) wt = FALL_TIME;
  var tk = Math.floor(wt * TICKS_PER_SEC + 0.0000001);
  if (tk < 0) tk = 0;
  var A = snapAt(tk);
  var B = snapAt(tk + 1);
  var f = wt * TICKS_PER_SEC - tk;
  if (f < 0) f = 0;
  if (f > 1) f = 1;
  if (HAS_FALL && t >= FALL_TIME - 0.0000001) f = 0;

  applyCameraShake(t);
  updateEnemies(A, B, f, wt, tk);
  updateTurrets(A, wt);
  updateBase(wt);
  updateParticles(t, wt);
  updateShots(t, wt);
  updatePulses(t, wt);
  updateHUD(A, t);
  updateDesaturation(t);

  renderer.clear(true, true, true);
  renderer.render(scene, camera);
  renderer.clearDepth();
  renderer.render(hudScene, hudCamera);
}

function updateDesaturation(t) {
  var sat = 1;
  if (HAS_FALL && t >= FALL_TIME) {
    var a = Math.min(1, (t - FALL_TIME) / 1.0);
    sat = 1 - a * 0.96;
    if (sat < 0.04) sat = 0.04;
  }
  if (sat < 0.999) {
    stage.style.filter = "saturate(" + sat.toFixed(3) + ")";
  } else if (stage.style.filter) {
    stage.style.filter = "";
  }
}

function frameLoop(now) {
  window.requestAnimationFrame(frameLoop);
  if (lastWall === null) {
    lastWall = now;
    renderScene(simTime);
    return;
  }
  var rawDt = (now - lastWall) / 1000;
  lastWall = now;
  var dt = Math.min(Math.max(rawDt, 0), 0.1);

  if (playbackState === COUNTDOWN) {
    countdownElapsed += dt;
    if (countdownElapsed < 3) {
      updateCountdownDisplay();
      renderScene(0);
      return;
    }
    hideCountdown();
    countdownElapsed = 0;
    var carry = Math.min(dt, 0.1);
    simTime = 0;
    playbackState = PLAYING;
    setPlayIcons(true);
    setAudioAudible(true);
    resetAudioCursor(0);
    var prev = 0;
    simTime = Math.min(DURATION, simTime + carry * playbackSpeed);
    setScrubberValue(simTime.toFixed(3));
    renderScene(simTime);
    processAudio(prev, simTime);
    if (simTime >= DURATION) enterEnded();
    return;
  }

  if (playbackState === PLAYING) {
    var prevT = simTime;
    simTime = Math.min(DURATION, simTime + dt * playbackSpeed);
    setScrubberValue(simTime.toFixed(3));
    renderScene(simTime);
    processAudio(prevT, simTime);
    if (simTime >= DURATION) enterEnded();
    return;
  }

  if (playbackState === REFIRE_HOLD) {
    holdElapsed += dt;
    renderScene(0);
    if (holdElapsed >= 1.0) {
      holdElapsed = 0;
      enterPlaying();
      resetAudioCursor(0);
    }
    return;
  }

  // PAUSED / ENDED hold their deterministic frame
  renderScene(playbackState === ENDED ? DURATION : simTime);
}

// ---------------- controls ----------------
btnToggle.addEventListener("click", function () {
  if (playbackState === PLAYING) {
    enterPaused();
  } else if (playbackState === COUNTDOWN || playbackState === REFIRE_HOLD) {
    hideCountdown();
    simTime = 0;
    setScrubberValue("0");
    renderScene(0);
    enterPaused();
  } else if (playbackState === PAUSED) {
    enterPlaying();
  } else if (playbackState === ENDED) {
    simTime = 0;
    setScrubberValue("0");
    hideCountdown();
    renderScene(0);
    enterPlaying();
  }
});

btnRefire.addEventListener("click", function () {
  enterRefire();
});

scrubber.addEventListener("input", function () {
  if (playbackState === COUNTDOWN || playbackState === REFIRE_HOLD) {
    hideCountdown();
    countdownElapsed = 0;
    holdElapsed = 0;
  }
  var v = parseFloat(scrubber.value);
  if (!(v >= 0)) v = 0;
  if (v > DURATION) v = DURATION;
  simTime = v;
  playbackState = PAUSED;
  setPlayIcons(false);
  setAudioAudible(false);
  resetAudioCursor(v);
  renderScene(v);
});

for (var spi = 0; spi < speedPills.length; spi++) {
  (function (pill) {
    pill.addEventListener("click", function () {
      playbackSpeed = parseFloat(pill.getAttribute("data-speed"));
      for (var i = 0; i < speedPills.length; i++) {
        var p = speedPills[i];
