      pushFlash(tx, ty, tz, 0.9 + p * 0.7, 0xff5a70, 0.9 * (1 - p));
    } else if (typ === 1) {
      if (p < 0.62) {
        var cp = p / 0.62;
        var shx = fx + (tx - fx) * cp;
        var shz = fz + (tz - fz) * cp;
        var shy = 0.5 + (ty - 0.5) * cp + Math.sin(cp * Math.PI) * 1.15;
        pushShell(shx, shy, shz, 0.16, 0xffbb78, 1);
        pushFlash(shx, shy, shz, 0.5, 0xffb066, 0.7 * (1 - cp));
