      pushRing(tx, ty + 0.2, tz, 0.14 + 0.56 * p, 0x59f2e2, (1 - p) * 0.95);
      pushFlash(tx, ty + 0.15, tz, 1.1, 0x8bfff2, 0.8 * (1 - p));
    }
    var mcol = [0x9fc8ff, 0xffc27a, 0xd8f4ff, 0xff6378, 0x7affef][typ] || 0xffffff;
    pushFlash(fx, 0.52, fz, 0.62, mcol, 0.85 * (1 - p));
  }
  finalizeEffects();
}

