/* Late-game sell/replace experiment.  Dev-only. */
function mkLate(types, replaceSlot, startWave, targetType) {
  var base = mkMap(types, BORDER, BORDER, "t2cheap", "smart");
  var cost = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
  return function createStrategy() {
    var b = base();
    return {
      plan: function (s) {
        var acts = b.plan(s);
        var map = {};
        for (var i = 0; i < s.slots.length; i++) {
          var sl = s.slots[i];
          map[sl.slot] = sl.turret ? { type: sl.turret.type, tier: sl.turret.tier, spent: sl.turret.spent } : null;
        }
        var budget = s.gold;
        for (var a = 0; a < acts.length; a++) {
          var ac = acts[a];
          var tu = map[ac.slot];
          if (ac.op === "build") { budget -= cost[ac.type]; map[ac.slot] = { type: ac.type, tier: 1, spent: cost[ac.type] }; }
          else if (ac.op === "upgrade") { var cc = cost[tu.type] * (tu.tier === 1 ? 1 : 2); budget -= cc; tu.tier++; tu.spent += cc; }
          else if (ac.op === "sell") { budget += Math.floor(tu.spent * 70 / 100); map[ac.slot] = null; }
        }
        if (s.wave >= startWave && map[replaceSlot] && map[replaceSlot].tier === 3 && map[replaceSlot].type !== targetType) {
          var cur = map[replaceSlot];
          var refund = Math.floor(cur.spent * 70 / 100);
          var need = cost[targetType] * 4 - refund; // build + up + up = 4x base cost
          if (budget >= need) {
            acts.push({ op: "sell", slot: replaceSlot });
            budget += refund;
            acts.push({ op: "build", slot: replaceSlot, type: targetType });
            budget -= cost[targetType];
            acts.push({ op: "upgrade", slot: replaceSlot });
            acts.push({ op: "upgrade", slot: replaceSlot });
            budget -= cost[targetType] * 3;
            map[replaceSlot] = { type: targetType, tier: 3, spent: cost[targetType] * 4 };
          }
        }
        return acts;
      },
      target: b.target
    };
  };
}

